~~~/src/Component.tsx
/**
 * Strategic Analytics Dashboard - Main Component
 * 
 * A highly detailed, gamified, interactive analytics dashboard with:
 * - 3-column layout with strategic imperatives, main content, and quick actions
 * - Top header navigation with dark mode toggle
 * - Modular reporting cards with click-to-expand functionality (FIXED at bottom)
 * - Interactive charts with animated progress bars
 * - Micro-animations on all UI elements (200ms ease-in-out transitions)
 * - Immersive dark theme matching Novartis/IDSync design system
 * - Bottom metric cards fixed and spanning full dashboard width
 */

import { motion, AnimatePresence } from 'framer-motion';
import { useState } from 'react';
import { Header } from './components/Header';
import { Navigation } from './components/Navigation';
import { StrategicImperatives } from './components/StrategicImperatives';
import { ProjectHealthHeader } from './components/ProjectHealthHeader';
import { PillarCard } from './components/PillarCard';
import { HealthChart } from './components/HealthChart';
import { MetricCard } from './components/MetricCard';
import { QuickActions } from './components/QuickActions';
import { KeyInsights } from './components/KeyInsights';
import { DetailedReportOverlay } from './components/DetailedReportOverlay';
import { pillars, metricCards } from './data/mockData';

export function StrategicAnalyticsDashboard() {
  const [isDarkMode, setIsDarkMode] = useState(true);
  // Track single expanded metric ID for accordion-style behavior
  const [expandedMetricId, setExpandedMetricId] = useState<string | null>(null);

  // Track detailed report view
  const [detailedReportId, setDetailedReportId] = useState<string | null>(null);

  const toggleMetricExpand = (id: string) => {
    // If clicking the already expanded card, close it. Otherwise open the new one.
    setExpandedMetricId(currentId => currentId === id ? null : id);
  };

  const hasExpandedMetrics = expandedMetricId !== null;

  return (
    <div className={`h-screen overflow-hidden flex flex-col transition-colors duration-500 ${isDarkMode ? 'bg-[#161616] text-white' : 'bg-[#FCFCFC] text-[#161616]'}`}>
      <style>{`
        * {
          transition: background-color 0.5s ease-in-out, border-color 0.5s ease-in-out, color 0.3s ease-in-out !important;
        }
        .main-scroll::-webkit-scrollbar {
          width: 6px;
        }
        .main-scroll::-webkit-scrollbar-track {
          background: transparent;
        }
        .main-scroll::-webkit-scrollbar-thumb {
          background: ${isDarkMode ? '#3b82f6' : '#C5C5C5'};
          border-radius: 3px;
        }
        body {
          background-color: ${isDarkMode ? '#161616' : '#FCFCFC'};
          transition: background-color 0.5s ease-in-out;
        }
      `}</style>
      <AnimatePresence>
        {detailedReportId && (
          <DetailedReportOverlay 
            isOpen={true} 
            onClose={() => setDetailedReportId(null)} 
            metricId={detailedReportId}
            isDarkMode={isDarkMode}
          />
        )}
      </AnimatePresence>

      {/* Background Pattern */}
      <div 
        className="fixed inset-0 opacity-30 pointer-events-none"
        style={{
          backgroundImage: isDarkMode ? `
            radial-gradient(ellipse 80% 50% at 50% -20%, rgba(59, 130, 246, 0.15), transparent),
            radial-gradient(ellipse 60% 40% at 100% 100%, rgba(34, 197, 94, 0.1), transparent)
          ` : 'none'
        }}
      />

      {/* Grid Pattern Overlay */}
      <div 
        className="fixed inset-0 opacity-5 pointer-events-none"
        style={{
          backgroundImage: isDarkMode ? `
            linear-gradient(rgba(255,255,255,0.05) 1px, transparent 1px),
            linear-gradient(90deg, rgba(255,255,255,0.05) 1px, transparent 1px)
          ` : `
            linear-gradient(rgba(0,0,0,0.05) 1px, transparent 1px),
            linear-gradient(90deg, rgba(0,0,0,0.05) 1px, transparent 1px)
          `,
          backgroundSize: '50px 50px'
        }}
      />

      {/* Header - Fixed */}
      <div className="relative z-20 flex-shrink-0">
        <Header isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} />
        <Navigation className="z-30" isDarkMode={isDarkMode} />
      </div>

      {/* Main Content Area - Scrollable, with padding for fixed bottom cards */}
      <div className="relative z-10 flex flex-1 overflow-hidden" style={{ paddingBottom: '160px' }}>
        {/* Left Sidebar - Strategic Imperatives with Vertical Scrollbar */}
        <motion.div
          className="w-[280px] flex-shrink-0 overflow-hidden relative z-40"
          initial={{ x: -100, opacity: 0 }}
          animate={{ x: 0, opacity: 1 }}
          transition={{ duration: 0.5, delay: 0.2 }}
        >
          <StrategicImperatives className="h-full" isDarkMode={isDarkMode} />
        </motion.div>

        {/* Center Content - Scrollable */}
        <motion.div
          className="flex-1 p-6 overflow-y-auto main-scroll"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.3 }}
          style={{
            scrollbarWidth: 'thin',
            scrollbarColor: isDarkMode ? '#3b82f6 transparent' : '#C5C5C5 transparent'
          }}
        >
          {/* Project Health Header */}
          <ProjectHealthHeader isDarkMode={isDarkMode} />

          {/* Pillar Cards */}
          <div className="grid grid-cols-4 gap-3 mb-6">
            {pillars.map((pillar, index) => (
              <PillarCard key={pillar.id} pillar={pillar} index={index} isDarkMode={isDarkMode} />
            ))}
          </div>

          {/* Health Chart */}
          <div className="mb-6">
            <HealthChart isDarkMode={isDarkMode} />
          </div>

          {/* Spacer for scrolling under fixed cards */}
          <div className="h-4" />
        </motion.div>

        {/* Right Sidebar */}
        <motion.div
          className={`w-[280px] flex-shrink-0 p-6 border-l overflow-y-auto transition-colors duration-500 ${isDarkMode ? 'bg-[#161616] border-[#939393]' : 'bg-[#FCFCFC] border-[#C5C5C5]'}`}
          initial={{ x: 100, opacity: 0 }}
          animate={{ x: 0, opacity: 1 }}
          transition={{ duration: 0.5, delay: 0.4 }}
          style={{
            scrollbarWidth: 'thin',
            scrollbarColor: isDarkMode ? '#3b82f6 transparent' : '#C5C5C5 transparent'
          }}
        >
          <QuickActions isDarkMode={isDarkMode} />
          <KeyInsights isDarkMode={isDarkMode} />
        </motion.div>
      </div>

      {/* Fixed Bottom Metric Cards - Full Width */}
      <motion.div
        className="fixed bottom-0 left-0 right-0 z-30"
        initial={{ y: 100, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 0.5, delay: 0.5 }}
        style={{
          pointerEvents: 'none' // Allow clicking through the empty space above cards
        }}
      >
        {/* Fixed height background gradient for collapsed state */}
        <div className={`absolute bottom-0 left-0 right-0 h-[160px] transition-colors duration-500 pointer-events-none ${
          isDarkMode ? 'bg-gradient-to-t from-[#161616] via-[#161616] to-transparent' : 'bg-gradient-to-t from-[#FCFCFC] via-[#FCFCFC] to-transparent'
        }`} />

        <motion.div
          className="flex gap-3 px-4 pb-4 items-end relative z-10 h-full"
          layout
          style={{ pointerEvents: 'auto' }} // Re-enable pointer events for the cards
        >
          {metricCards.map((metric, index) => (
            <MetricCard
              key={metric.id}
              metric={metric}
              index={index}
              isExpanded={expandedMetricId === metric.id}
              onToggle={() => toggleMetricExpand(metric.id)}
              onViewDetails={() => setDetailedReportId(metric.id)}
              hasExpandedItem={hasExpandedMetrics}
              isDarkMode={isDarkMode}
            />
          ))}
        </motion.div>
      </motion.div>
    </div>
  );
}

export default StrategicAnalyticsDashboard;
~~~

