~~~/src/hooks/useExpandable.ts
/**
 * Custom hook for managing expandable card states
 * Handles expansion logic, active card tracking, and animation states
 */

import { useState, useCallback } from 'react';

export function useExpandable() {
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const toggleExpand = useCallback((id: string) => {
    setExpandedId((prev) => (prev === id ? null : id));
  }, []);

  const isExpanded = useCallback(
    (id: string) => expandedId === id,
    [expandedId]
  );

  const hasExpandedItem = expandedId !== null;

  return {
    expandedId,
    toggleExpand,
    isExpanded,
    hasExpandedItem,
    closeAll: () => setExpandedId(null),
  };
}
