/**
 * Metric Card Component with Expandable Details
 * Bottom row metric cards - FIXED position at bottom of dashboard
 * Cards span equal width across the full dashboard width
 * Features animated badges, icons, and interactive states
 */

import { motion, AnimatePresence } from 'framer-motion';
import { ArrowUpRight, CheckCircle, Layers, GitBranch, Clock, X } from 'lucide-react';
import { useState } from 'react';
import { MetricCard as MetricCardType } from '../types';

const iconMap = {
  projects: CheckCircle,
  requests: Layers,
  progress: GitBranch,
  pending: Clock,
};

const colorMap = {
  projects: '#22c55e',
  requests: '#3b82f6',
  progress: '#f59e0b',
  pending: '#8b5cf6',
};

interface MetricCardProps {
  metric: MetricCardType;
  index: number;
  isExpanded: boolean;
  onToggle: () => void;
  onViewDetails: () => void;
  hasExpandedItem: boolean;
  isDarkMode: boolean;
}

export function MetricCard({ metric, index, isExpanded, onToggle, onViewDetails, hasExpandedItem, isDarkMode }: MetricCardProps) {
  const Icon = iconMap[metric.icon as keyof typeof iconMap] || CheckCircle;
  const color = colorMap[metric.icon as keyof typeof colorMap] || '#3b82f6';
  const [isHovered, setIsHovered] = useState(false);

  return (
    <motion.div
      layout
      className={`relative border rounded-xl overflow-hidden cursor-pointer flex-1 min-w-0 transition-colors duration-500 ${
        isDarkMode 
          ? 'bg-gradient-to-b from-[#484848] to-[#2f2f2f] border-[#616161]' 
          : 'bg-[#FCFCFC] border-[#C5C5C5] shadow-sm'
      } ${
        hasExpandedItem && !isExpanded ? 'opacity-70' : ''
      }`}
      onClick={onToggle}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      initial={{ opacity: 0, y: 30 }}
      animate={{ 
        opacity: hasExpandedItem && !isExpanded ? 0.7 : 1, 
        y: 0,
        scale: hasExpandedItem && !isExpanded ? 0.98 : 1,
      }}
      whileHover={{ 
        scale: isExpanded ? 1 : 1.02, 
        borderColor: color,
        boxShadow: isDarkMode ? `0 0 30px ${color}30` : `0 4px 15px ${color}20`
      }}
      transition={{ duration: 0.2, ease: [0.25, 0.1, 0.25, 1] }}
    >
      {/* Glow Effect */}
      <motion.div
        className="absolute inset-0 opacity-0"
        style={{ 
          background: `radial-gradient(circle at 50% 0%, ${color}20 0%, transparent 70%)` 
        }}
        animate={{ opacity: isHovered || isExpanded ? 1 : 0 }}
        transition={{ duration: 0.3 }}
      />

      <div className="relative p-4 flex gap-4 h-full">
        {/* Left Column: Vertical Icon Stack - Full Height */}
        <div className="flex flex-col items-center gap-3 shrink-0 pr-4">
          <motion.div 
            className="flex flex-col gap-3 h-full"
            animate={{ scale: isHovered ? 1.05 : 1 }}
          >
