/**
 * Navigation Component for the Strategic Analytics Dashboard
 * Horizontal tab navigation with active states and hover animations
 * Features smooth transitions and interactive feedback
 */

import { motion } from 'framer-motion';
import { LayoutDashboard, FileInput, Users, HeartPulse, CalendarDays } from 'lucide-react';
import { useState } from 'react';

const tabs = [
  { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { id: 'request-intake', label: 'Request Intake', icon: FileInput },
  { id: 'collaboration', label: 'Collaboration & Approvals', icon: Users },
  { id: 'project-health', label: 'Project Health', icon: HeartPulse, isActive: true },
  { id: 'timelines', label: 'Timelines', icon: CalendarDays },
];

export function Navigation({ className = "", isDarkMode }: { className?: string, isDarkMode: boolean }) {
  const [activeTab, setActiveTab] = useState('project-health');

  return (
    <nav className={`transition-colors duration-500 border-b relative ${className} ${
      isDarkMode ? 'bg-[#2f2f2f] border-[#484848]' : 'bg-[#FCFCFC] border-[#C5C5C5]'
    }`}>
      <div className="flex items-center justify-center px-6">
        {tabs.map((tab) => {
          const Icon = tab.icon;
          const isActive = activeTab === tab.id;

          return (
            <motion.button
              key={tab.id}
              className={`relative flex items-center gap-2 px-5 py-4 text-sm transition-colors ${
                isActive 
                  ? (isDarkMode ? 'text-[#22c55e]' : 'text-[#FF4E00]') 
                  : (isDarkMode ? 'text-white/60 hover:text-white/90' : 'text-[#616161] hover:text-[#161616]')
              }`}
              onClick={() => setActiveTab(tab.id)}
              whileHover={{ y: -2 }}
              whileTap={{ scale: 0.98 }}
              transition={{ duration: 0.2, ease: 'easeInOut' }}
            >
              <Icon size={18} />
              <span>{tab.label}</span>

              {/* Active indicator */}
              {isActive && (
                <motion.div
                  className={`absolute bottom-0 left-0 right-0 h-0.5 ${isDarkMode ? 'bg-gradient-to-r from-[#22c55e] to-[#3b82f6]' : 'bg-[#FF4E00]'}`}
                  layoutId="activeTab"
                  transition={{ duration: 0.3, ease: 'easeInOut' }}
                />
              )}

              {/* Hover glow effect */}
              <motion.div
                className={`absolute inset-0 rounded-t-lg opacity-0 ${isDarkMode ? 'bg-gradient-to-b from-[#22c55e]/0 to-[#22c55e]/5' : 'bg-[#FF4E00]/5'}`}
                whileHover={{ opacity: isActive ? 0.5 : 0.3 }}
                transition={{ duration: 0.2 }}
              />
            </motion.button>
          );
        })}
      </div>
    </nav>
  );
}

export default Navigation;
