              activeDot={{ r: 6, strokeWidth: 2 }}
              onMouseEnter={() => setHoveredLine('dataEnablement')}
              onMouseLeave={() => setHoveredLine(null)}
              style={{ filter: hoveredLine && hoveredLine !== 'dataEnablement' ? 'opacity(0.3)' : 'none' }}
            />
            <Line
              type="monotone"
