              strokeWidth={hoveredLine === 'humanInsights' || !hoveredLine ? 2.5 : 1}
              dot={{
                fill: '#ef4444',
                strokeWidth: 2,
                r: hoveredLine === 'humanInsights' ? 5 : 3,
              }}
              activeDot={{ r: 6, strokeWidth: 2 }}
