              activeDot={{ r: 6, strokeWidth: 2 }}
              onMouseEnter={() => setHoveredLine('aiInnovation')}
              onMouseLeave={() => setHoveredLine(null)}
              style={{ filter: hoveredLine && hoveredLine !== 'aiInnovation' ? 'opacity(0.3)' : 'none' }}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Legend */}
      <div className="flex items-center justify-center gap-6 mt-4">
        {pillars.map((pillar) => (
          <motion.div
            key={pillar.id}
