/**
 * Custom hook for animated progress bar values
 * Provides smooth counting animation from 0 to target value
 */

import { useState, useEffect } from 'react';

export function useAnimatedProgress(targetValue: number, duration: number = 1500) {
  const [currentValue, setCurrentValue] = useState(0);
  const [isAnimating, setIsAnimating] = useState(false);

  useEffect(() => {
    setIsAnimating(true);
    const startTime = Date.now();
    const startValue = 0;

    const animate = () => {
      const now = Date.now();
      const elapsed = now - startTime;
      const progress = Math.min(elapsed / duration, 1);

      // Easing function for smooth animation
      const easeOutCubic = 1 - Math.pow(1 - progress, 3);
      const value = startValue + (targetValue - startValue) * easeOutCubic;

      setCurrentValue(Math.round(value));

      if (progress < 1) {
        requestAnimationFrame(animate);
      } else {
        setIsAnimating(false);
      }
    };

    requestAnimationFrame(animate);
  }, [targetValue, duration]);

  return { currentValue, isAnimating };
}
